SELECT  FROM sdk_spel_rule_release
WHERE tenant_id = #{tenantId} AND rule_set_code = #{ruleSetCode}
ORDER BY release_version DESC LIMIT 100

SELECT  FROM sdk_spel_rule_release
WHERE tenant_id = #{tenantId} AND rule_set_code = #{ruleSetCode}
  AND release_version = #{releaseVersion} LIMIT 1

SELECT  FROM sdk_spel_rule_release
WHERE tenant_id = #{tenantId} AND scene = #{scene}
  AND release_id > #{afterCursor} ORDER BY release_id LIMIT #{limit}
